/*
 * A042171  Denominators of continued fraction convergents to sqrt(610).
 * https://oeis.org/A042171
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, frac, easy
 * Formula:   a(n) = denominator of the nth convergent of the continued *
 *            fraction expansion of sqrt(610). The recurrence is * * q_{-2} =
 *            1, q_{-1} = 0 * q_n = a_n * q_{n-1} + q_{n-2} * * where the
 *            partial quotients (a_n) for sqrt(610) are generated by * the
 *            standard continued‑fraction algorithm
 * Range:     u8 n <= 4, u16 n <= 8, u32 n <= 17, u64 n <= 35, u128 n <= 67,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

seq_t a(idx_t n)
{
    /* Constants for sqrt(610) */
    const uint64_t D   = 610;
    const uint64_t a0  = 24;          /* floor(sqrt(610)) */

    /* Continued fraction state: m, d, a_current */
    uint64_t m = 0;
    uint64_t d = 1;
    uint64_t a_current = a0;

    /* Convergent denominators */
    seq_t q_prev2 = 1;   /* q_{-2} */
    seq_t q_prev1 = 0;   /* q_{-1} */

    /* Iterate up to the requested index */
    for (idx_t i = 0; i <= n; ++i) {
        seq_t q_curr = ((seq_t)a_current) * q_prev1 + q_prev2;

        if (i == n)
            return q_curr;

        /* Compute next partial quotient */
        uint64_t m_next  = d * a_current - m;
        uint64_t d_next  = (D - m_next * m_next) / d;
        uint64_t a_next  = (a0 + m_next) / d_next;

        m = m_next;
        d = d_next;
        a_current = a_next;

        /* Shift denominators for next iteration */
        q_prev2 = q_prev1;
        q_prev1 = q_curr;
    }

    /* This point is unreachable but keeps the compiler happy */
    return 0;
}
